<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/notifications.php';send_cors_headers();$auth=require_auth();$userId=auth_user_id($auth);$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT r.*,p.name AS product_name FROM product_reviews r JOIN products p ON p.id=r.product_id WHERE r.user_id=:user ORDER BY r.created_at DESC');$stmt->execute(['user'=>$userId]);json_response(200,['success'=>true,'reviews'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$itemId=(int)($body['order_item_id']??0);$rating=(int)($body['rating']??0);$title=trim((string)($body['title']??''));$text=trim((string)($body['review_text']??''));if($rating<1||$rating>5||mb_strlen($text)<10||mb_strlen($text)>3000)json_response(422,['success'=>false,'message'=>'Rating and review text are required.']);$stmt=$db->prepare('SELECT oi.*,o.user_id,g.status AS group_status FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN vendor_order_groups g ON g.id=oi.vendor_group_id WHERE oi.id=:item AND o.user_id=:user');$stmt->execute(['item'=>$itemId,'user'=>$userId]);$item=$stmt->fetch();if(!$item||$item['group_status']!=='delivered')json_response(422,['success'=>false,'message'=>'Only delivered purchases can be reviewed.']);$id=uuid_string();try{$db->prepare('INSERT INTO product_reviews (id,user_id,order_item_id,product_id,vendor_id,rating,title,review_text,status,created_at) VALUES (:id,:user,:item,:product,:vendor,:rating,:title,:text,"published",UTC_TIMESTAMP())')->execute(['id'=>$id,'user'=>$userId,'item'=>$itemId,'product'=>$item['product_id'],'vendor'=>$item['vendor_id'],'rating'=>$rating,'title'=>$title?:null,'text'=>$text]);}catch(PDOException $e){if((string)$e->getCode()==='23000')json_response(409,['success'=>false,'message'=>'You already reviewed this item.']);throw $e;}create_notification('vendor',$item['vendor_id'],'new_review','New verified review',"A customer left a {$rating}-star review.",'../reviews.php',['review_id'=>$id]);json_response(201,['success'=>true,'message'=>'Review published.','review_id'=>$id]);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
